<script>
document.addEventListener('DOMContentLoaded',function(){
 var form=document.getElementById('complaintCreateForm'),modal=document.getElementById('complaintConfirmModal'),confirmButton=document.getElementById('confirmComplaintSubmit'),cancelButton=document.getElementById('cancelComplaintSubmit'),submitting=false;
 form.addEventListener('submit',function(event){if(submitting)return;event.preventDefault();document.getElementById('confirmComplaintSubject').textContent=form.elements.subject.value;document.getElementById('confirmComplaintCategory').textContent=form.elements.category.options[form.elements.category.selectedIndex].text;document.getElementById('confirmComplaintPriority').textContent=form.elements.priority.options[form.elements.priority.selectedIndex].text;modal.classList.remove('d-none');confirmButton.focus();});
 function closeModal(){modal.classList.add('d-none');}
 cancelButton.addEventListener('click',closeModal);modal.addEventListener('click',function(event){if(event.target===modal)closeModal();});document.addEventListener('keydown',function(event){if(event.key==='Escape'&&!modal.classList.contains('d-none'))closeModal();});
 confirmButton.addEventListener('click',function(){if(submitting)return;submitting=true;confirmButton.disabled=true;cancelButton.disabled=true;confirmButton.innerHTML='<i class="fa fa-spinner fa-spin"></i> Submitting...';form.submit();});
 document.getElementById('complaintAttachment').addEventListener('change',function(){var help=document.getElementById('complaintAttachmentHelp'),file=this.files[0];help.textContent=file?file.name+' · '+(file.size/1024/1024).toFixed(2)+' MB':'PDF, JPG or PNG · maximum 10 MB';});
});
</script>
